namespace Novior.MentorAgent.Abstractions.Models;

/// <summary>
/// The argument of the hub's <c>ReplyStarted</c> event, sent once before the first <c>StreamingChunk</c> of each reply
/// MentorAgent generates: <c>{ "aiGenerated": true }</c>. It is the machine-readable marker of AI-generated text on the
/// hub, where the chunks themselves carry only their text. More properties may be added.
/// </summary>
public sealed record MentorReplyStarted
{
    /// <summary>Always true: the reply that follows is generated by an AI model.</summary>
    public bool AiGenerated { get; init; } = true;
}
